import React from 'react';

function App() {
  return (
    <div style={styles.container}>
      <h1>Welcome to My CRM Dashboard</h1>
      <p>This is a sample React component.</p>
    </div>
  );
}

const styles = {
  container: {
    padding: '2rem',
    fontFamily: 'Arial',
    textAlign: 'center',
  },
};

export default App;
